// Tombstone service worker. (#34)
//
// 이 블로그는 2026-07-13까지 Chirpy(PWA)였고, Chirpy가 /blog/sw.min.js에 서비스 워커를
// 등록해 사이트를 통째로 캐시했다. Type Theme로 옮기면서 그 파일은 사라졌지만(서버에서 404)
// 브라우저에 등록된 워커는 스스로 사라지지 않아, 모든 요청을 가로채 포스트 없는 옛 캐시를
// 계속 내준다.
//
// 브라우저는 in-scope 내비게이션 시 이 스크립트를 주기적으로(최대 ~24h) 네트워크에서 다시
// 받아 업데이트를 확인한다(top-level 스크립트는 기본적으로 HTTP 캐시를 우회). 지금 이 200
// tombstone을 받으면 캐시된 Chirpy 워커와 바이트가 달라 새로 설치·활성화되고, 아래 activate에서
// 캐시를 비우고 자기 자신을 unregister한 뒤 열린 탭을 새로고침한다. 영향받은 브라우저가 저절로
// 복구된다.
//
// Type Theme는 register()를 부르지 않으므로 새 방문자는 이 파일을 절대 받지 않는다 — 이미 워커가
// 등록된 브라우저만 업데이트 확인 때 받는다.
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil((async function () {
    try { await self.clients.claim(); } catch (e) {}
    const keys = await caches.keys();
    await Promise.all(keys.map(function (k) { return caches.delete(k); }));
    await self.registration.unregister();
    const clients = await self.clients.matchAll({ type: 'window' });
    for (const client of clients) {
      try { client.navigate(client.url); } catch (e) {}
    }
  })());
});
